/*
 * Bakes the pixel-art PNG sheets and atlas JSON for direction C from the code in
 * src/fx/pixel, and writes upscaled previews to docs/art/pixel/. Run from the repo root:
 *   node assets/art/pixel/build.mjs
 * Outputs (assets/art/pixel/): pixel-player.png/.json, pixel-tiles.png/.json, pixel-scenery.png/.json.
 * All art is generated by this repo's own code (CC0 / MIT, nothing third-party).
 */
import { createServer } from 'vite';
import { deflateSync } from 'node:zlib';
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..', '..', '..');
const previewDir = path.join(root, 'docs', 'art', 'pixel');
mkdirSync(previewDir, { recursive: true });

// ---- PNG encoder (RGBA8, no interlace, filter 0) ---------------------------
const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 255] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, 'ascii');
  data.copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
};
function encodePng(r) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(r.width, 0);
  ihdr.writeUInt32BE(r.height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  const raw = Buffer.alloc((r.width * 4 + 1) * r.height);
  for (let y = 0; y < r.height; y++) {
    raw[y * (r.width * 4 + 1)] = 0;
    Buffer.from(r.data.buffer, r.data.byteOffset + y * r.width * 4, r.width * 4).copy(raw, y * (r.width * 4 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

const server = await createServer({
  root,
  configFile: false,
  logLevel: 'silent',
  appType: 'custom',
  server: { middlewareMode: true },
});
try {
  const px = await server.ssrLoadModule('/src/fx/pixel/index.ts');
  const fx = await server.ssrLoadModule('/src/fx/palette.ts');
  const assets = px.buildPixelAssets();
  for (const [name, atlas] of Object.entries(assets)) {
    writeFileSync(path.join(here, `pixel-${name}.png`), encodePng(atlas.sheet));
    writeFileSync(path.join(here, `pixel-${name}.json`), JSON.stringify(atlas.json, null, 1) + '\n');
  }
  const bg = (speed) => fx.backgroundForSpeed(speed, 12);

  // ---- preview 1: every player frame, both runners, yellow, plus all bands idle ----
  const K = 3;
  const sheet = px.createRaster(14 * 20 + 10, 6 * 28 + 10);
  const field = px.rgba(bg(0));
  px.fillRect(sheet, 0, 0, sheet.width, sheet.height, field);
  const place = (frame, x, y) => px.blit(sheet, frame, x, y);
  let row = 0;
  for (const variant of ['runner', 'twin']) {
    px.PLAYER_FRAMES.forEach((def, i) => place(px.bakePlayerFrame(variant, 'yellow', def), 5 + (i % 14) * 20, 5 + (row + Math.floor(i / 14)) * 28));
    row += 2;
  }
  ['white', 'blue', 'green', 'yellow', 'red'].forEach((band, i) => {
    place(px.bakePlayerFrame('runner', band, px.PLAYER_FRAMES[0]), 5 + i * 20, 5 + 4 * 28);
    place(px.bakePlayerFrame('twin', band, px.PLAYER_FRAMES[0]), 5 + (i + 6) * 20, 5 + 4 * 28);
    place(px.bakePlayerFrame('runner', band, px.PLAYER_FRAMES.find((f) => f.name === 'run_1')), 5 + i * 20, 5 + 5 * 28);
    place(px.bakePlayerFrame('twin', band, px.PLAYER_FRAMES.find((f) => f.name === 'sprint_2')), 5 + (i + 6) * 20, 5 + 5 * 28);
  });
  writeFileSync(path.join(previewDir, 'player-frames.png'), encodePng(px.upscale(sheet, K)));

  // ---- preview 2: the w0-02 slice assembled only from baked assets (480x270 -> 960x540) ----
  const GRID = [
    '..............................', '..............................', '..............................',
    '..............................', '..............................', '..............................',
    '.....................#########', '.....................#########', '..............................',
    '..............................', '..............................', '..............................',
    '##########RRRRR######.YYY#BBB#', '##########.....######....#...#', '##########.....######....#...#',
    '##########.....######....#.E.#', '##########.....######....#####',
  ];
  const BAND_OF = { B: 'blue', G: 'green', Y: 'yellow', R: 'red' };
  const at = (c, r) => (r < 0 || r >= GRID.length || c < 0 || c >= GRID[0].length ? '.' : GRID[r][c]);
  const compose = (band, speed, runner, frameName) => {
    const out = px.createRaster(480, 270);
    const colors = px.sceneryColors(speed, 12);
    px.fillRect(out, 0, 0, 480, 270, px.rgba(colors.base));
    const tintMask = (mask, color, x, y, alpha = 255) => {
      for (let j = 0; j < mask.height; j++) for (let i = 0; i < mask.width; i++) if (px.getPixel(mask, i, j)[3] > 0) px.setPixel(out, x + i, y + j, px.rgba(color, alpha));
    };
    const horizon = px.bakeHorizon();
    const hz = px.createRaster(480, 270);
    for (let j = 0; j < 270; j++) for (let i = 0; i < 480; i++) if (px.getPixel(horizon, i, j)[3] > 0 && px.bayer(i, j) < colors.horizonAlpha) px.setPixel(hz, i, j, [255, 255, 255, 255]);
    tintMask(hz, colors.hue, 0, 0);
    tintMask(px.bakeStars(), colors.star, 0, 0);
    tintMask(px.bakeRidge('far'), colors.ridgeFar, 0, px.RIDGES.far.top);
    tintMask(px.bakeRidge('near'), colors.ridgeNear, 0, px.RIDGES.near.top);
    for (let r = 0; r < GRID.length; r++) {
      for (let c = 0; c < 30; c++) {
        const ch = at(c, r);
        if (ch === '.') continue;
        const x = c * 16;
        const y = r * 16 - 2;
        const same = (dc, dr) => at(c + dc, r + dr) === ch;
        const n = { up: same(0, -1), right: same(1, 0), down: same(0, 1), left: same(-1, 0) };
        if (ch === '#') {
          let depth = 0;
          for (let k = 1; k <= 4 && at(c, r - k) === '#'; k++) depth = k;
          px.blit(out, px.bakeSafeTile(n, depth), x, y);
        } else if (ch === 'E') {
          px.blit(out, px.bakeExitGlow(1), x - 8, y - 8);
          px.blit(out, px.bakeExitDoor(1), x, y);
        } else {
          const b = BAND_OF[ch];
          px.blit(out, b === band ? px.bakeSolidTile(b, n) : px.bakeGhostTile(b), x, y);
        }
      }
    }
    const def = px.PLAYER_FRAMES.find((f) => f.name === frameName);
    px.blit(out, px.bakePlayerFrame(runner, band, def), 100 - 10, 190 - 26);
    return out;
  };
  writeFileSync(path.join(previewDir, 'scene-yellow.png'), encodePng(px.upscale(compose('yellow', 9, 'runner', 'run_2'), 2)));
  writeFileSync(path.join(previewDir, 'scene-red.png'), encodePng(px.upscale(compose('red', 12, 'runner', 'sprint_2'), 2)));
  writeFileSync(path.join(previewDir, 'scene-white-b.png'), encodePng(px.upscale(compose('white', 0, 'twin', 'idle_0'), 2)));
} finally {
  await server.close();
}
